/**
 * Scan codegen sources for clocks, randomness, unordered iteration, and
 * localeCompare whose order can reach generated output.
 *
 * Allow a finding with a comment on the same line or the line above:
 *   determinism-allow: <why this never reaches generated bytes, or why order is source order>
 * A file header comment suppresses iteration findings only (not clocks or localeCompare):
 *   determinism-allow-file: <why>
 * Clock, random, and localeCompare calls always need their own comment.
 * Strings and comments are not scanned: a Date.now inside an emitted template is source text.
 *
 * localeCompare() with no locale follows LANG. da, lt, et, and cs reorder
 * committed JSON. Use compareEnUs from packages/core/src/order.ts instead.
 */
import { readdirSync, readFileSync, statSync } from 'node:fs';
import { relative, join, sep } from 'node:path';
import { repoRoot } from '../../core/src/toolchain.js';
import { EXTERNAL_ALLOW } from './allow.js';

export interface Finding {
  file: string;
  line: number;
  kind: 'clock' | 'iteration' | 'locale';
  message: string;
}

const ROOTS = [
  'packages/deluge/src',
  'packages/ui/src',
  'packages/ui-react/src',
  'packages/schema/src',
  'packages/deploy/src/plan.ts',
  'packages/deploy/src/function-dir.ts',
  'packages/deploy/src/mail.ts',
  'packages/core/src/ir.ts',
  'packages/core/src/parse.ts',
  'packages/core/src/cst.ts',
  'packages/core/src/lexer.ts',
  'packages/core/src/source.ts',
  'packages/core/src/zml.ts',
  'packages/core/src/toolchain.ts',
  // Seed file order is a generator tie-break. migrate.ts in the same folder is runtime, not codegen.
  'packages/data/src/seed.ts',
];

/**
 * Generators that write a committed file but also use source-order Set spreads
 * the iteration rules already accept elsewhere. Only localeCompare is gated here.
 */
const LOCALE_FILES = [
  'packages/deluge/scripts/scrape-builtin-docs.mjs',
];

export function lintCodegen(root = repoRoot()): Finding[] {
  const files: string[] = [];
  for (const rel of ROOTS) {
    const abs = join(root, rel);
    const st = statSync(abs, { throwIfNoEntry: false });
    if (!st) continue;
    if (st.isDirectory()) walk(abs, files);
    else files.push(abs);
  }
  files.sort((a, b) => (a < b ? -1 : a > b ? 1 : 0));
  const findings: Finding[] = [];
  for (const abs of files) {
    const rel = relative(root, abs).split(sep).join('/');
    findings.push(...scanSource(rel, readFileSync(abs, 'utf8')));
  }
  for (const rel of LOCALE_FILES) {
    const abs = join(root, rel);
    if (!statSync(abs, { throwIfNoEntry: false })) continue;
    findings.push(...scanSource(rel, readFileSync(abs, 'utf8')).filter((f) => f.kind === 'locale'));
  }
  return findings;
}

export function formatFindings(findings: readonly Finding[]): string {
  return findings.map((f) => `${f.file}:${f.line}: ${f.message}`).join('\n');
}

function walk(dir: string, out: string[]): void {
  for (const name of readdirSync(dir).sort((a, b) => (a < b ? -1 : a > b ? 1 : 0))) {
    if (name === 'node_modules') continue;
    const p = join(dir, name);
    const st = statSync(p);
    if (st.isDirectory()) walk(p, out);
    else if (/\.(ts|js|mjs)$/.test(name) && !name.endsWith('.d.ts')) out.push(p);
  }
}

export function scanSource(file: string, src: string): Finding[] {
  const masked = maskNonCode(src);
  const findings: Finding[] = [];
  const bindings = mapSetBindings(masked);

  for (const match of masked.matchAll(/\bDate\s*\.\s*now\s*\(/g)) {
    note(findings, src, file, match.index, 'clock', 'Date.now()');
  }
  for (const match of masked.matchAll(/\bnew\s+Date\s*\(\s*\)/g)) {
    note(findings, src, file, match.index, 'clock', 'new Date() with no arguments');
  }
  for (const match of masked.matchAll(/\bMath\s*\.\s*random\s*\(/g)) {
    note(findings, src, file, match.index, 'clock', 'Math.random()');
  }
  for (const match of masked.matchAll(/\brandomUUID\s*\(/g)) {
    note(findings, src, file, match.index, 'clock', 'randomUUID()');
  }
  for (const match of masked.matchAll(/\bperformance\s*\.\s*now\s*\(/g)) {
    note(findings, src, file, match.index, 'clock', 'performance.now()');
  }
  for (const match of masked.matchAll(/\bprocess\s*\.\s*hrtime(?:\s*\.\s*bigint)?\s*\(/g)) {
    note(findings, src, file, match.index, 'clock', 'process.hrtime()');
  }
  for (const match of masked.matchAll(/\.localeCompare\s*\(/g)) {
    note(findings, src, file, match.index, 'locale', 'localeCompare() follows the process locale and can reorder generated output');
  }

  for (const match of masked.matchAll(/\bObject\s*\.\s*(keys|entries|values)\s*\(/g)) {
    const paren = masked.indexOf('(', match.index);
    if (isLengthOnly(masked, paren)) continue;
    if (chainHasSort(masked, paren)) continue;
    note(findings, src, file, match.index, 'iteration', `Object.${match[1]}() without .sort() where order can reach output`);
  }

  scanForOf(masked, src, file, bindings, findings);
  scanSpreads(masked, src, file, bindings, findings);
  return findings;
}

function note(
  findings: Finding[],
  src: string,
  file: string,
  index: number,
  kind: 'clock' | 'iteration' | 'locale',
  message: string,
): void {
  if (allowed(src, file, index, kind)) return;
  findings.push({ file, line: lineNumber(src, index), kind, message });
}

function allowed(src: string, file: string, index: number, kind: 'clock' | 'iteration' | 'locale'): boolean {
  const line = lineNumber(src, index);
  const cur = lineText(src, line);
  const prev = line > 1 ? lineText(src, line - 1) : '';
  if (justified(cur) || justified(prev)) return true;
  if (kind === 'iteration' && /^[^\n]*determinism-allow-file\s*:\s*\S/m.test(src)) return true;
  const around = src.slice(Math.max(0, index - 60), index + 80);
  return EXTERNAL_ALLOW.some((rule) => rule.file === file && rule.kind === kind && around.includes(rule.snippet));
}

function justified(line: string): boolean {
  const match = /determinism-allow\s*:\s*(\S.*)$/.exec(line);
  return !!match && match[1].trim().length > 0;
}

function lineNumber(src: string, index: number): number {
  let line = 1;
  for (let i = 0; i < index && i < src.length; i++) if (src[i] === '\n') line++;
  return line;
}

function lineText(src: string, line: number): string {
  return src.split('\n')[line - 1] ?? '';
}

function mapSetBindings(masked: string): Set<string> {
  const names = new Set<string>();
  for (const match of masked.matchAll(/(?:const|let|var)\s+([A-Za-z_$][\w$]*)\s*=\s*new\s+(?:Map|Set)\b/g)) {
    names.add(match[1]);
  }
  return names;
}

function isLengthOnly(src: string, openParen: number): boolean {
  const close = matchingClose(src, openParen);
  if (close < 0) return false;
  let j = close + 1;
  while (j < src.length && /\s/.test(src[j])) j++;
  if (!src.startsWith('.length', j)) return false;
  j += '.length'.length;
  while (j < src.length && /\s/.test(src[j])) j++;
  return j >= src.length || (src[j] !== '.' && src[j] !== '[');
}

/** True when a call or a `[...]` chain later calls .sort( before the expression ends. */
function chainHasSort(src: string, start: number): boolean {
  let i = start;
  let depth = 0;
  while (i < src.length) {
    const c = src[i];
    if (c === '(' || c === '[' || c === '{') {
      depth++;
      i++;
      continue;
    }
    if (c === ')' || c === ']' || c === '}') {
      if (depth === 0) return false;
      depth--;
      i++;
      if (depth === 0) {
        let j = i;
        while (j < src.length && /[ \t\r\n]/.test(src[j])) j++;
        if (src.startsWith('.sort(', j)) return true;
        if (src[j] === '.' || src[j] === '[') {
          i = j;
          continue;
        }
        return false;
      }
      continue;
    }
    if ((c === ';' || c === ',') && depth === 0) return false;
    if (depth === 0 && src.startsWith('.sort(', i)) return true;
    i++;
  }
  return false;
}

function matchingClose(src: string, open: number): number {
  const pair: Record<string, string> = { '(': ')', '[': ']', '{': '}' };
  const want = pair[src[open]];
  if (!want) return -1;
  let depth = 0;
  for (let i = open; i < src.length; i++) {
    const c = src[i];
    if (c === src[open]) depth++;
    else if (c === want) {
      depth--;
      if (depth === 0) return i;
    }
  }
  return -1;
}

function scanForOf(masked: string, src: string, file: string, bindings: Set<string>, findings: Finding[]): void {
  for (const match of masked.matchAll(/\bfor\s*\(/g)) {
    const paren = match.index + match[0].length - 1;
    const close = matchingClose(masked, paren);
    if (close < 0) continue;
    const header = masked.slice(paren + 1, close);
    const ofAt = ofKeyword(header);
    if (ofAt < 0) continue;
    const expr = header.slice(ofAt + 4).trim();
    if (expr.includes('.sort(')) continue;
    const iterates = /\.(?:keys|values|entries)\s*\(/.test(expr);
    const ident = /^([A-Za-z_$][\w$]*)$/.exec(expr);
    const bound = ident ? bindings.has(ident[1]) : false;
    if (!iterates && !bound) continue;
    note(
      findings,
      src,
      file,
      paren + 1 + ofAt,
      'iteration',
      `for-of over ${bound ? 'Map/Set' : 'keys/values/entries'} without .sort()`,
    );
  }
}

function ofKeyword(header: string): number {
  let depth = 0;
  for (let i = 0; i < header.length; i++) {
    const c = header[i];
    if (c === '(' || c === '[' || c === '{') depth++;
    else if (c === ')' || c === ']' || c === '}') depth--;
    else if (depth === 0 && c === 'o' && header.startsWith('of', i) && (i === 0 || /\s/.test(header[i - 1])) && /\s/.test(header[i + 2] ?? '')) {
      return i;
    }
  }
  return -1;
}

function scanSpreads(masked: string, src: string, file: string, bindings: Set<string>, findings: Finding[]): void {
  for (const match of masked.matchAll(/\[\s*\.\.\.\s*new\s+(?:Set|Map)\b/g)) {
    if (chainHasSort(masked, match.index)) continue;
    note(findings, src, file, match.index, 'iteration', 'spread of new Set/Map without .sort()');
  }
  for (const match of masked.matchAll(/\[\s*\.\.\.[^\]]*?\.(?:keys|values|entries)\s*\(/g)) {
    if (chainHasSort(masked, match.index)) continue;
    note(findings, src, file, match.index, 'iteration', 'spread of keys/values/entries without .sort()');
  }
  for (const match of masked.matchAll(/\[\s*\.\.\.\s*([A-Za-z_$][\w$]*)\b/g)) {
    if (!bindings.has(match[1])) continue;
    if (chainHasSort(masked, match.index)) continue;
    note(findings, src, file, match.index, 'iteration', `spread of Map/Set ${match[1]} without .sort()`);
  }
}

/**
 * Blank comments, strings, template text, and regex literals so the scan
 * sees generator code only. Newlines stay put, so indexes match the original.
 */
export function maskNonCode(src: string): string {
  const out = src.split('');
  const blank = (from: number, to: number) => {
    for (let k = from; k < to; k++) if (out[k] !== '\n') out[k] = ' ';
  };
  let i = 0;
  let last = '';
  const n = src.length;

  const mark = (token: string) => {
    if (token.trim()) last = token;
  };

  while (i < n) {
    const c = src[i];
    if (c === '/' && src[i + 1] === '/') {
      const start = i;
      i += 2;
      while (i < n && src[i] !== '\n') i++;
      blank(start, i);
      continue;
    }
    if (c === '/' && src[i + 1] === '*') {
      const start = i;
      i += 2;
      while (i < n && !(src[i] === '*' && src[i + 1] === '/')) i++;
      i = Math.min(n, i + 2);
      blank(start, i);
      continue;
    }
    if (c === '/' && canStartRegex(last)) {
      const start = i;
      i++;
      while (i < n) {
        if (src[i] === '\\') {
          i += 2;
          continue;
        }
        if (src[i] === '\n') break;
        if (src[i] === '/') {
          i++;
          while (i < n && /[a-z]/i.test(src[i])) i++;
          break;
        }
        i++;
      }
      blank(start, i);
      last = '/';
      continue;
    }
    if (c === "'" || c === '"') {
      const q = c;
      const start = i;
      i++;
      while (i < n) {
        if (src[i] === '\\') {
          i += 2;
          continue;
        }
        if (src[i] === '\n') break;
        if (src[i] === q) {
          i++;
          break;
        }
        i++;
      }
      blank(start, i);
      last = q;
      continue;
    }
    if (c === '`') {
      i = maskTemplate(src, out, i, blank);
      last = '`';
      continue;
    }
    if (/[A-Za-z_$]/.test(c)) {
      const start = i;
      i++;
      while (i < n && /[\w$]/.test(src[i])) i++;
      mark(src.slice(start, i));
      continue;
    }
    if (!/\s/.test(c)) last = c;
    i++;
  }
  return out.join('');
}

function maskTemplate(
  src: string,
  out: string[],
  start: number,
  blank: (from: number, to: number) => void,
): number {
  let i = start + 1;
  let text = start;
  const n = src.length;
  while (i < n) {
    if (src[i] === '\\') {
      i += 2;
      continue;
    }
    if (src[i] === '`') {
      blank(text, i + 1);
      return i + 1;
    }
    if (src[i] === '$' && src[i + 1] === '{') {
      blank(text, i);
      i += 2;
      i = maskCodeUntilBrace(src, out, i, blank);
      text = i;
      continue;
    }
    i++;
  }
  blank(text, n);
  return n;
}

/** Scan code inside ${ ... }, honoring nested strings and braces. Returns the index after `}`. */
function maskCodeUntilBrace(
  src: string,
  out: string[],
  start: number,
  blank: (from: number, to: number) => void,
): number {
  let i = start;
  let depth = 0;
  let last = '';
  const n = src.length;
  while (i < n) {
    const c = src[i];
    if (c === '/' && src[i + 1] === '/') {
      const from = i;
      i += 2;
      while (i < n && src[i] !== '\n') i++;
      blank(from, i);
      continue;
    }
    if (c === '/' && src[i + 1] === '*') {
      const from = i;
      i += 2;
      while (i < n && !(src[i] === '*' && src[i + 1] === '/')) i++;
      i = Math.min(n, i + 2);
      blank(from, i);
      continue;
    }
    if (c === '/' && canStartRegex(last)) {
      const from = i;
      i++;
      while (i < n && src[i] !== '\n' && src[i] !== '/') {
        if (src[i] === '\\') i += 2;
        else i++;
      }
      if (src[i] === '/') i++;
      blank(from, i);
      last = '/';
      continue;
    }
    if (c === "'" || c === '"') {
      const q = c;
      const from = i;
      i++;
      while (i < n && src[i] !== '\n' && src[i] !== q) {
        if (src[i] === '\\') i += 2;
        else i++;
      }
      if (src[i] === q) i++;
      blank(from, i);
      last = q;
      continue;
    }
    if (c === '`') {
      i = maskTemplate(src, out, i, blank);
      last = '`';
      continue;
    }
    if (c === '{') {
      depth++;
      last = c;
      i++;
      continue;
    }
    if (c === '}') {
      if (depth === 0) return i + 1;
      depth--;
      last = c;
      i++;
      continue;
    }
    if (/[A-Za-z_$]/.test(c)) {
      const from = i;
      i++;
      while (i < n && /[\w$]/.test(src[i])) i++;
      last = src.slice(from, i);
      continue;
    }
    if (!/\s/.test(c)) last = c;
    i++;
  }
  return n;
}

function canStartRegex(last: string): boolean {
  return (
    last === '' ||
    last === 'return' ||
    last === 'case' ||
    last === 'throw' ||
    last === 'typeof' ||
    last === 'void' ||
    last === 'do' ||
    last === 'else' ||
    last === 'in' ||
    last === 'of' ||
    /[(\[=,:;!&|?{+\-*%~^<>]/.test(last)
  );
}
